  if (repair.status === "customer_accepted") return "Thanks for accepting. Our team will contact you to arrange the repair visit.";
  if (repair.status === "admin_approved") return "Your warranty claim is approved. Our team will arrange the service visit.";
  if (repair.status === "scheduled") return "Your repair visit is scheduled. Check the dates below for the service window.";
  if (repair.status === "in_progress") return "Our team is working on your repair. Weâ€™ll post an update when it is complete.";
